-- Read-only, after the first poll. Generated by Build-Sql.py.
SELECT 'undated|' || publisher_id || '|' || count(*) || '|in window=' || count(*) FILTER (WHERE fetched_at > now() - interval '14 days')
  FROM articles WHERE publisher_id IN (8917, 8918, 8925, 8949, 8956) AND published_at IS NULL GROUP BY publisher_id ORDER BY publisher_id;
SELECT 'new|' || publisher_id || '|' || count(*) || ' since apply|' || count(*) FILTER (WHERE published_at IS NULL) || ' undated|newest ' || coalesce(to_char(max(published_at), 'MM-DD HH24:MI'), '-')
  FROM articles WHERE publisher_id IN (8917, 8918, 8925, 8949, 8956) AND fetched_at > now() - interval '40 minutes' GROUP BY publisher_id ORDER BY 1;
SELECT 'silent|' || p.id || '|' || p.name || '|' || coalesce(to_char(max(a.published_at), 'MM-DD'), 'never')
  FROM publishers p LEFT JOIN articles a ON a.publisher_id = p.id AND a.published_at IS NOT NULL AND a.published_at < now() + interval '1 day'
 WHERE p.id IN (8917, 8918, 8925, 8949, 8956) GROUP BY p.id, p.name ORDER BY p.id;
